export function greet(name) {
  return `hello ${name}`
}

export function add(a, b) {
  return a + b
}

export class Calc {
  constructor(base) {
    this.base = base
  }

  multiply(x) {
    return this.base * x
  }
}

export async function fetchCount(url) {
  return `count:${url.length}`
}

export const double = (x) => x * 2

export const greetArrow = (name) => `hi ${name}`

export const sumRest = (...nums) => nums.reduce((total, n) => total + n, 0)

export const withDefault = (a, b = 10) => a + b

export const pickName = ({ name, meta: { tag } }, [first, ...rest]) => `${name}:${tag}:${first}:${rest.length}`

export function callOuterArgs() {
  const inner = () => arguments[0] * 2
  return inner()
}

export const collide = (dshFabricArguments) => dshFabricArguments + 1

export async function withAwait(x) {
  const v = await Promise.resolve(x * 2)
  return v + 1
}

export function* counter(limit) {
  for (let i = 0; i < limit; i++) yield i
}

export async function* asyncCounter(limit) {
  for (let i = 0; i < limit; i++) yield i
}
